const INSTRUMENT = () => {
  const w = window;
  if (w.__probe) return;
  w.__probe = { ev: [], t0: performance.now() };
  const log = (type, detail) =>
    w.__probe.ev.push({ t: +(performance.now() - w.__probe.t0).toFixed(1), type, detail });
  w.__probeMark = (label) => log("MARK", label);

  const hasFrame = (n) =>
